from h import *
R(9318277,"أسهل وأنعم فطائر نباتية على الإطلاق",
"يمكن أن تكون أنعم فطائر نباتية في طبقك في وقت قصير بفضل هذه الوصفة البسيطة جدًا المكونة من 4 مكونات.",
"10 فطائر","فطيرة واحدة",
["1 كوب دقيق متعدد الاستخدامات غير مبيّض أو دقيق قمح كامل","1 كوب حليب الكاجو غير المحلى أو أي حليب خالٍ من الألبان من اختيارك","1 ملعقة كبيرة بيكنج باودر","1 ملعقة كبيرة سكر جوز الهند غير المكرر، اختياري","1 ملعقة صغيرة مستخلص الفانيليا الطبيعي، اختياري"],
["ضع الدقيق والسكر والبيكنج باودر في وعاء كبير واخفقها حتى تمتزج. ثم أضف الحليب والفانيليا وقلّب حتى تمتزج، دون إفراط في الخلط.","سخّن صينية القلي غير اللاصقة على نار متوسطة، وعندما تسخن، اسكب العجين بالمغرفة لتحصل على فطائر قطرها حوالي 4 بوصات. اطهِها لمدة 3-5 دقائق تقريبًا حتى تتكون عدة فقاعات على سطحها. ثم اقلبها واطهِ الجانب الآخر لمدة 3-5 دقائق أخرى حتى تنضج تمامًا.","قدّمها مع شراب القيقب أو الفاكهة الطازجة واستمتع بها."],
["لا تُفرط في خلط عجين الفطائر. إذا وُجدت بعض الكتل الصغيرة فلا بأس بذلك إطلاقًا. لا تنجرف إلى الخلط حتى يصبح العجين ناعمًا تمامًا، فقد يغيّر ذلك قوام الفطائر. سخّن المقلاة أو صينية القلي مسبقًا. يجب أن تكون ساخنة قبل سكب العجين لمنع الالتصاق ولينضج بالتساوي. استخدم نارًا متوسطة لطهي الفطائر. ورغم أنه يجب أن تكون المقلاة ساخنة، فهذا لا يعني استخدام نار عالية. فقد يؤدي ذلك إلى نضج غير متساوٍ، بخارج مقرمش وداخل طري. اقلب الفطائر مرة واحدة فقط. ستظهر الفقاعات على سطح الفطائر بعد وقت قصير من بدء الطهي، لكن انتظر حتى تظهر عدة فقاعات وحتى تُطهى الفطيرة لمدة 3-4 دقائق على الأقل قبل قلبها. فالقلب المتكرر قد يجعلها تنكمش وتفقد هشاشتها الرائعة. تصلح هذه الفطائر أيضًا مع دقيق القمح الكامل. ستكون أقل هشاشة قليلًا لكنها تبقى لذيذة. طعم الفطائر أفضل وهي طازجة، لكن يمكنك حفظ المتبقي في الثلاجة وإعادة تسخينه في محمصة الخبز لتناوله خلال 1-2 يوم. ويمكنك أيضًا تجميدها وإعادة تسخينها في محمصة الخبز وهي مجمدة."])
R(9320396,"معكرونة الكوسا النباتية بصلصة البولونيز",
"صلصة بولونيز خضار غنية ومشبعة ولذيذة بشكل لا يصدق، تُقدَّم فوق معكرونة الكوسا النباتية المقطعة حلزونيًا، طبقك المريح الأمثل الذي لا تشعر معه بالذنب!",
"5 حصص","حصة واحدة",
["6 حبات كوسا متوسطة","1 كوب جوز أو بذور قرع نيئة","½ كوب طماطم مجففة بالشمس","4-5 أكواب زهيرات قرنبيط، أي حوالي نصف قرنبيطة متوسطة","8 أونصات فطر كريميني، أي حوالي 8-10 حبات فطر صغيرة","32 أونصة (4 أكواب) صلصة طماطم أو هريس طماطم من اختيارك","1 ملعقة صغيرة مسحوق الثوم","½ ملعقة صغيرة أوريجانو مجفف","½ ملعقة صغيرة ريحان مجفف","ملح + فلفل حسب الرغبة","جبن بارميزان نباتي","رقائق الفلفل الحار","ريحان طازج أو بقدونس"],
["حوّل الكوسا إلى شرائح حلزونية باستخدام قطّاعة حلزونية. ضع المعكرونة في مصفاة موضوعة فوق وعاء كبير ورشّ الكوسا بسخاء بالملح. قلّبها بيديك واتركها جانبًا لمدة 30 دقيقة أو أكثر. (إذا كنت تحضّر مسبقًا، فيمكنك فعل هذه الخطوة قبل الطهي بعدة ساعات.)","في هذه الأثناء، ضع الجوز والطماطم المجففة بالشمس في محضّر الطعام وقلّب بالنبض حتى يصبح الخليط مفتتًا دون إفراط في الفرم. أبقِه خشنًا. انقله إلى مقلاة عميقة.","اعمل على دفعات صغيرة وفرم القرنبيط والفطر بعد ذلك. مرة أخرى، أبقِ القوام مفتتًا ولا تفرط في الفرم. انقلهما إلى المقلاة نفسها التي فيها خليط الجوز وأضف جميع التوابل.","اخلط جيدًا وقلّب على النار لمدة 5-7 دقائق حتى تلين الخضار ويقل حجمها. ثم اسكب صلصة الطماطم ودعها تغلي على نار هادئة لمدة 10-15 دقيقة.","وأخيرًا، سخّن معكرونة الكوسا برفق في مقلاة لمدة 1-2 دقيقة. لا تطهُها وإلا أصبحت طرية جدًا. فقط دفّئها. ثم قدّمها مع صلصة البولونيز."],
["لا تُفرط في فرم الخضار. فطعم الصلصة أفضل عندما يكون لها قوام.","إذا بقيت بعض القطع الكبيرة العنيدة أثناء فرم الخضار، فأضفها إلى الدفعة التالية بدلًا من مواصلة فرمها، حتى لا تُفرط في فرم بقية الخضار.","لا تُفرط في طهي معكرونة الكوسا. فطعمها أفضل عندما يكون فيها قوام متماسك قليلًا.","انقل معكرونة الكوسا إلى الأطباق فور تدفئتها. ولا تتركها في المقلاة الساخنة وقتًا طويلًا وإلا أصبحت طرية جدًا.","لوصفة خالية من المكسرات، استخدم بذور القرع أو بذور دوار الشمس.","لوصفة خالية من الزيت، استخدم الطماطم المجففة بالشمس التي تأتي في كيس مفرّغ من الهواء وليس المعبأة في برطمان.","احفظ الصلصة المتبقية ومعكرونة الكوسا في وعاءين منفصلين لمنع تحوّلها إلى قوام رخو، وذلك لمدة تصل إلى 3 أيام."],
{"Optional Garnishes":"للتزيين (اختياري)"})
R(9322650,"ناجتس الحمص المخبوزة [خالية من مسببات الحساسية]",
"ناجتس الحمص المقرمشة اللذيذة ذات النكهة الرائعة سهلة التحضير جدًا وتُخبز بإتقان.",
"3 حصص (تعطي 15 قطعة ناجتس)","حصة واحدة",
["علبة حمص 15 أونصة مصفّاة ومشطوفة (أو 1½ كوب مطبوخ)","¼ كوب طماطم مجففة بالشمس مكبوسة برفق","½ حبة بصل أحمر صغيرة مقطعة تقطيعًا خشنًا","2-3 فصوص ثوم مقشّرة","½ ملعقة صغيرة بهارات الدواجن","½ ملعقة صغيرة ملح البحر","2 ملعقة كبيرة شوفان مجروش، خالٍ من الغلوتين إن أردت","مايونيز السريراتشا","كاتشب","خردل بالعسل النباتي"],
["سخّن الفرن مسبقًا على 400 درجة فهرنهايت (200 درجة مئوية) وبطّن صينية خبز بورق الزبدة. ضعها جانبًا.","ضع جميع المكونات في محضّر الطعام وقلّب بالنبض حتى تُفرم ناعمًا وتمتزج، دون أن تتحول إلى هريس. (أبقِ بعض القوام.)","اضغط خليط الحمص بيديك لتشكيل كرات بحجم كرة الغولف، ثم افرِدها برفق وشكّلها على هيئة أقراص. ضعها على صينية الخبز وكرر العملية مع بقية الخليط. ستحصل على 15 قطعة ناجتس.","اخبزها لمدة 25-30 دقيقة، مع قلبها مرة واحدة عند منتصف المدة. قدّمها مع صلصة غمس من اختيارك واستمتع بها."],
["يُرجى الانتباه إلى أن ناجتس الحمص هذه لا يشبه طعمها الدجاج. فهي ليست بديلًا نباتيًا لناجتس الدجاج. إنها لذيذة ورائعة بحد ذاتها! لا تُفرط في فرم المكونات. اترك بعض القطع الخشنة للحصول على أفضل قوام للناجتس. توخَّ الحذر عند القلب. لا تجبر قطع الناجتس على الانقلاب إذا لم تنفصل بسهولة عن ورق الزبدة وإلا فقد تنكسر. إذا لم تنفصل بسهولة، فأعد الصينية إلى الفرن لبضع دقائق أخرى وحاول مجددًا. فكلما طال طهيها سهل قلبها. يختلف وقت الخَبز بحسب حجم قطع الناجتس. يبقى المتبقي صالحًا في الثلاجة لمدة 3-4 أيام في وعاء محكم الإغلاق أو يُجمَّد في وعاء محكم الإغلاق لمدة تصل إلى 3 أشهر. افصل بين طبقات الناجتس بورق الزبدة لمنع الالتصاق. حجم الحصة يعادل ⅓ الوصفة، أي حوالي 5 قطع ناجتس."],
{"Optional Dipping Sauces":"صلصات غمس اختيارية"})
R(9323221,"سيتان بنكهة الدجاج مارسالا",
"هذا الطبق الإيطالي الكلاسيكي بنسخته النباتية سيذهلك! دجاج السيتان مارسالا طري وغني بالعصارة ومليء بالنكهة ومن الصعب التوقف عنه!",
"6 حصص","حصة واحدة",
["½ كوب فاصولياء كانيليني بيضاء","2 ملعقة كبيرة طحينة","3 ملاعق كبيرة خميرة غذائية","2 ملعقة صغيرة مسحوق البصل","2 ملعقة صغيرة مسحوق الثوم","2 ملعقة صغيرة بهارات الدواجن","1 ملعقة صغيرة ملح البحر","⅔ كوب مرق خضار","210 جرامات من غلوتين القمح الحيوي، أي حوالي 1¾ كوب","3-4 أكواب مرق خضار","2 كوب مرق خضار مقسّمة","½ كوب كاجو نيء","1-2 ملعقة كبيرة زبدة نباتية، اختيارية، واستخدم الماء أو المرق لوصفة خالية من الزيت","8 أونصات فطر كريميني مقطع شرائح","2-3 فصوص ثوم مفرومة","⅛ ملعقة صغيرة زعتر مجفف","⅔ كوب نبيذ مارسالا","بقدونس طازج للتزيين"],
["سخّن الفرن مسبقًا على 350 درجة فهرنهايت (175 درجة مئوية).","ضع جميع مكونات الدجاج النباتي في محضّر الطعام ما عدا غلوتين القمح الحيوي واخلطها حتى تصبح ناعمة. ثم أضف نصف غلوتين القمح الحيوي وقلّب بالنبض حتى يمتزج. أضف النصف المتبقي وقلّب بالنبض حتى يمتزج مرة أخرى.","انقل الخليط إلى سطح نظيف أو لوح تقطيع واعجنه لمدة 30 ثانية تقريبًا، دون إفراط. شكّل العجينة على هيئة أسطوانة أو قرص وقسّمها إلى 6 قطع متساوية الحجم تقريبًا. (يمكنك استخدام ميزان المطبخ إذا أردتها متساوية تمامًا، لكن ذلك ليس ضروريًا.)","استخدم راحة يدك أو مدحاة العجين لتسطيح كل قطعة على شكل \"شريحة دجاج\". ليس من الضروري أن تبدو مثالية. افردها رقيقة لأن حجمها سيتضاعف تقريبًا عند الطهي.","استخدم وعاءً يصلح للفرن وله غطاء، مثل القدر الهولندي، وضع في قاعه طبقة رقيقة من مرق الخضار. ثم رتّب الشرائح بداخله على طبقتين، وأضف مرقًا كافيًا لتغطيتها تمامًا بحوالي بوصة فوق الطبقة العلوية. ضع الغطاء وأدخله الفرن لمدة 80 دقيقة ثم أخرجه.","إذا كنت تحضّرها مسبقًا، فانقل الشرائح إلى وعاء واحفظها في الثلاجة طوال الليل وأكمل الطهي في يوم التقديم. (احتفظ بالمرق لشربه، فهو لذيذ، فلا تسكبه! 😉)","بينما الشرائح في الفرن، حضّر الصلصة. أولًا، ضع الكاجو مع كوب واحد من مرق الخضار في خلاط عالي السرعة لتحضير \"الكريمة\" المخفوقة. اخلط حتى يصبح ناعمًا وضعه جانبًا.","في مقلاة كبيرة وعميقة، ذوّب الزبدة (إن استخدمتها) وأضف الفطر المقطع شرائح والثوم والزعتر. قلّب حتى يقل حجم الفطر، أي حوالي 3-4 دقائق.","ثم اسكب المارسالا والكوب المتبقي من المرق وكريمة الكاجو النباتية التي حضّرتها للتو. اتركها تغلي على نار متوسطة لمدة 5-8 دقائق حتى تتكاثف قليلًا.","بعد إخراج الشرائح من الفرن، انقلها إلى المقلاة التي فيها الصلصة واتركها تغلي معًا لمدة 2-3 دقائق. قدّمها مع البقدونس الطازج واستمتع بها."],
["إذا لم يكن لديك خلاط عالي السرعة، فانقع الكاجو مسبقًا في ماء ساخن لمدة 30 دقيقة ثم صفّه قبل الخلط ليتفتت بسهولة أكبر. استخدم ميزان المطبخ لوزن غلوتين القمح الحيوي للحصول على أدق النتائج والقوام. بالنسبة للمرق، احرص على استخدام نوع غني بالنكهة تحبه. أحب هذه النسخة. سيمتص دجاج السيتان بعض نكهة المرق أثناء الخَبز، لذا لا تستخدم نوعًا خفيف النكهة. لا تُفرط في عجن العجينة. يكفي العجن حتى ترى خيوطًا تتكون، أي حوالي 30 ثانية. للحصول على حصص متساوية الحجم، استخدم ميزان المطبخ عند تقسيم العجينة إلى ست قطع. هذا ليس ضروريًا تمامًا، بل فقط إن أردتها مثالية. استخدم وعاءً يصلح للفرن وله غطاء للخَبز. وإذا لم يكن لديك وعاء له غطاء، فاستخدم أي وعاء عميق يصلح للفرن وغطِّ سطحه بطبقة من ورق الزبدة ثم ورق الألمنيوم. افرد شرائح الدجاج النباتي رقيقة. فسيتضاعف حجمها تقريبًا في الفرن. أنت تريد أن تغلي الشرائح على نار هادئة في المرق وليس أن تفور بقوة. فالطهي البطيء يعطي أفضل قوام. لا ترفع درجة حرارة الفرن في محاولة لإنضاجها أسرع. يبقى المتبقي صالحًا في الثلاجة في وعاء محكم الإغلاق لمدة 3-4 أيام أو يُجمَّد في وعاء محكم الإغلاق مناسب للتجميد لمدة تصل إلى 6 أشهر."],
{"For the seitan chicken":"لدجاج السيتان","For cooking liquid":"لسائل الطهي","For the Marsala sauce":"لصلصة المارسالا","For Serving (Optional)":"للتقديم (اختياري)"})
R(9327187,"بطاطس مهروسة بقلاية الهواء",
"مقرمشة من الخارج وهشة من الداخل. هذه البطاطس المهروسة بقلاية الهواء بنكهة الثوم الشهية لا بد من تجربتها!",
"4 حصص","حصة واحدة",
["1 رطل بطاطس يوكون جولد، أي حوالي 4 حبات صغيرة","2 ملعقة كبيرة زبدة نباتية أو سمن نباتي (مارجرين) مذاب، أو استبدله بزيت الطهي إن أردت، أو مرق الخضار لوصفة خالية من الزيت","3 فصوص ثوم مقشّرة + مفرومة","1 ملعقة صغيرة بقدونس مجفف","½ ملعقة صغيرة ملح البحر أو حسب الرغبة","¼ ملعقة صغيرة فلفل أسود أو حسب الرغبة"],
["افرك البطاطس جيدًا جدًا لأنك ستأكل القشر. ثم ضعها في قدر واملأه بماء يغطيها بارتفاع بوصة فوقها. أضف ملعقة صغيرة من الملح وأوصل الماء إلى الغليان. اطهِها حتى تخترقها الشوكة وتبقى مع ذلك متماسكة، أي حوالي 18 دقيقة. لا تُفرط في الطهي وإلا تفتتت عند هرسها.","بينما تُطهى البطاطس، ذوّب الزبدة (إن استخدمتها) في قدر صغير. ثم أضف الثوم المفروم والتوابل وضعه جانبًا.","صفّ البطاطس وانقلها إلى لوح تقطيع واتركها لتبرد بضع دقائق حتى يسهل التعامل معها. استخدم شوكة كبيرة أو هرّاسة بطاطس لهرس البطاطس بحذر حتى تصبح مفلطحة بسمك نصف بوصة تقريبًا. (انتبه: لا تُفرط في هرسها وإلا قد تتفتت.)","افرد خليط الزبدة المتبّل على جانبَي البطاطس بالفرشاة وانقلها إلى السلة مع ترك مسافة كبيرة بين كل واحدة وأخرى. اقلِها بالهواء الساخن على 400 درجة فهرنهايت (200 درجة مئوية) لمدة 8-12 دقيقة، أو حتى تصل إلى درجة القرمشة المطلوبة."],
["ملّح ماء الطهي أو استخدم المرق لسلق البطاطس للحصول على نكهة أقوى. استخدم بطاطس صغيرة للحصول على أفضل النتائج. فالبطاطس الكبيرة تحتاج إلى وقت أطول للطهي ولن تصبح مقرمشة بالقدر نفسه ويصعب التعامل معها بعد هرسها. ضع البطاطس في السلة مع ترك مسافة كبيرة بين كل واحدة وأخرى لتدفق الهواء بشكل سليم ولكي لا تحتاج إلى قلبها. اترك البطاطس لتبرد بضع دقائق بعد السلق ليسهل التعامل معها وهرسها دون أن تتفتت."])
R(9327887,"سلطة الفراولة مع صلصة التوت الأزرق والريحان",
"حلوة وحامضة قليلًا وتفيض بالنكهة الطازجة، سلطة الفراولة والسبانخ هذه مع صلصة التوت الأزرق والريحان هي الصيف في كل لقمة.",
"4 حصص","حصة واحدة",
["5 أونصات سبانخ صغيرة (بيبي)","1 رطل فراولة طازجة (منزوعة العنق ومقطعة شرائح)","⅓ كوب لوز مقطع شرائح رفيعة","1 كوب توت أزرق","¼ كوب ريحان طازج","2 ملعقة كبيرة خل النبيذ الأبيض","1 ملعقة كبيرة شراب القيقب (اختياري)","ملح + فلفل (حسب الرغبة)"],
["ضع السبانخ الصغيرة وشرائح الفراولة واللوز في وعاء أو طبق تقديم.","ثم اخلط جميع مكونات صلصة السلطة في خلاط صغير. تذوّقها للتأكد من الملح والفلفل وعدّل حسب الحاجة.","رشّ الصلصة فوق السلطة، أو قدّمها في وعاء جانبي."],
[])
R(9328013,"سباغيتي البطاطا الحلوة [أليو إي أوليو]",
"تحصل معكرونة أليو إي أوليو على لمسة صحية مع سباغيتي البطاطا الحلوة هذه. إنها حارة بنكهة الثوم، ورغم اسمها، فهي خالية من الزيت!",
"4 حصص","حصة واحدة",
["4 حبات بطاطا حلوة متوسطة، استخدم حبات رفيعة وطويلة","¼ كوب أكوافابا أو مرق الخضار","4-5 فصوص ثوم مفرومة","2 ملعقة صغيرة بقدونس مجفف","1 ملعقة صغيرة فلاكس الفلفل الأحمر أو حسب الرغبة","½ ملعقة صغيرة ملح البحر أو حسب الرغبة","5 أونصات (142 جرامًا) سبانخ صغيرة (بيبي)، أي حوالي 4 أكواب مكبوسة","جبن بارميزان نباتي","فلاكس الفلفل الأحمر"],
["قشّر البطاطا الحلوة وحوّلها إلى سباغيتي باستخدام القطّاعة الحلزونية. ضعها جانبًا.","استخدم مقلاة كبيرة وأضف إليها الأكوافابا (أو المرق) مع الثوم والبقدونس وفلاكس الفلفل والملح. قلّب على نار متوسطة لمدة 2-3 دقائق مع المراقبة بعناية لمنع الاحتراق.","أضف سباغيتي البطاطا الحلوة إلى المقلاة وقلّب لتتغطى بالتوابل بالتساوي واطهِها على نار متوسطة إلى عالية لمدة 5-7 دقائق حتى تلين قليلًا، لكن لا تُفرط في الطهي. أضف بضع رشات من الماء أو المرق عند الحاجة لمنع التصاق المعكرونة بالمقلاة.","أطفئ النار وأضف السبانخ. قلّب حتى تذبل ثم قدّم."],
["لتسهيل التقطيع الحلزوني، استخدم بطاطا حلوة رفيعة وطويلة ومستقيمة. أو يمكنك شراء معكرونة البطاطا الحلوة المقطعة حلزونيًا مسبقًا من متجر البقالة لتوفير الوقت. إذا كنت تستخدم أكوافابا معلبة تحتوي على ملح، فقد ترغب في تقليل الملح في الوصفة، ثم تذوّق وأضف المزيد إذا لزم الأمر. لا تُفرط في طهي المعكرونة. فأنت تريدها طرية ومتماسكة قليلًا، وليست طرية جدًا، للحصول على أفضل قوام ولتحاكي معكرونة \"الدنتي\". إذا لم يكن لديك سبانخ، فيمكنك استبدالها بخضار ورقية أخرى. اسلق الخضار الورقية مسبقًا إذا لزم الأمر. لتقليل الحرارة، قلّل فلاكس الفلفل الأحمر إلى النصف. هذا الطبق حار تقليديًا، لكن احرص على ضبط الحرارة حسب ذوقك وتحمّلك. يبقى المتبقي صالحًا في الثلاجة في وعاء محكم الإغلاق لمدة 3-4 أيام."],
{"For Serving (optional)":"للتقديم (اختياري)"})
R(9329195,"شوربة الشعير والعدس",
"شوربة الشعير والعدس الدافئة والمشبعة مليئة بالحبوب الكاملة والخضار والمكونات البسيطة التي تُطهى ببطء لتمنحك الراحة.",
"6 حصص","حصة واحدة",
["1 ملعقة كبيرة زيت أفوكادو أو ¼ كوب مرق","1 حبة بصل أصفر مقطعة مكعبات","2-3 فصوص ثوم مفرومة","2 حبة جزر كبيرة مقطعة شرائح","2 عود كرفس مقطع شرائح","1 كوب عدس أخضر أو بني مشطوف ومنقّى","½ كوب شعير مقشور (لؤلؤي)","6 أكواب مرق خضار","1 كوب صلصة طماطم","2 ورقة غار","1 ملعقة صغيرة كمون","1 ملعقة صغيرة بابريكا مدخنة","5 أونصات سبانخ صغيرة (بيبي)","1-2 ملعقة كبيرة عصير ليمون","ملح + فلفل حسب الرغبة"],
["ضع زيت الطهي أو ¼ كوب من المرق في قدرك أو مقلاتك. ثم قلّب البصل والثوم والجزر والكرفس حتى تلين، أي حوالي 5 دقائق.","أضف العدس والشعير ومرق الخضار وصلصة الطماطم وورق الغار والكمون والبابريكا إلى القدر وقلّب كل شيء جيدًا. أوصلها إلى الغليان، ثم اخفض الحرارة ودعها تغلي على نار هادئة حتى ينضج العدس والشعير، أي حوالي 25 دقيقة.","أطفئ النار وأخرج ورق الغار. ثم أضف عصير الليمون والسبانخ الطازجة وقلّب حتى تذبل. تذوّق للتأكد من الملح والفلفل وعدّل حسب الحاجة."],
["استخدم مرقًا غنيًا بالنكهة! وإذا كان مرقك يفتقر إلى النكهة، فاحرص على تعديل التوابل.","إذا لم يكن لديك مرق في المنزل، فيمكنك تحضير مرق بوصفة المكعبات المركزة السهلة هذه. (أنصح بشدة بهذا المرق لنكهته الرائعة.)","بحسب القوام الذي تفضله، استخدم 6-8 أكواب من مرق الخضار. للحصول على شوربة أكثر كثافة، استخدم ستة أكواب. وللحصول على شوربة أخف، استخدم ثمانية. تذكّر: ستمتص الشوربة مزيدًا من السائل عندما تبرد.","يبقى المتبقي صالحًا في الثلاجة لمدة 3-4 أيام أو يُجمَّد لمدة تصل إلى 3 أشهر."])
save('/mnt/c/WSL/davita/translations/out_tar1_part3.json')
